                              '  /* Suspicious parent processes */\n'
                              '  process.parent.name : (\n'
                              '    "wsmprovhost.exe", "w3wp.exe", "wmiprvse.exe", "rundll32.exe", "regsvr32.exe"\n'
                              '  ) or\n'
                              '\n'
                              '  /* whoami execution under system privileges */\n'
                              '  (\n'
                              '    (\n'
                              '      (?process.Ext.token.integrity_level_name : "System" or '
                              '?winlog.event_data.IntegrityLevel : "System") or\n'
                              '      (\n'
                              '        user.domain : ("NT *", "* NT", "IIS APPPOOL") and\n'
                              '        user.id : ("S-1-5-18", "S-1-5-19", "S-1-5-20", "S-1-5-82-*") and\n'
                              '        not (?winlog.event_data.SubjectUserName : "*$" and '
                              '?winlog.event_data.SubjectUserName != null) and\n'
                              '\n'
                              '        /* Sysmon will always populate user.id as S-1-5-18, leading to FPs */\n'
                              '        not data_stream.dataset : ("windows.sysmon_operational", "windows.sysmon")\n'
                              '      )\n'
                              '    ) and\n'
                              '    not (\n'
                              '      (\n'
                              '        process.parent.name : "cmd.exe" and\n'
                              '        ?process.parent.args : (\n'
                              '          "chcp 437>nul 2>&1 & C:\\\\WINDOWS\\\\System32\\\\whoami.exe  /groups",\n'
